const canonicalSlug = value => String(value || '').normalize('NFKD').replace(/[^A-Za-z0-9]+/g, '_').replace(/^_|_$/g, '').toUpperCase() || 'UNNAMED';
const stableId = (prefix, value) => `${prefix}-${canonicalSlug(value)}`;
const PRODUCT_TYPE_REGISTRY = Object.freeze(Object.fromEntries(Object.entries(PRODUCT_TYPE_DEFINITIONS).flatMap(([categoryId, branches]) => Object.entries(branches).flatMap(([branch, definition]) => (definition.productTypes || []).map(label => [stableId(`PT-${categoryId}`, `${branch}-${label}`), Object.freeze({ id: stableId(`PT-${categoryId}`, `${branch}-${label}`), productTypeId: stableId(`PT-${categoryId}`, `${branch}-${label}`), categoryId, branch, subcategory: branch, label, status: 'ACTIVE' })])))));
const allDefinitions = () => Object.values(PRODUCT_TYPE_DEFINITIONS).flatMap(branches => Object.values(branches));
const uniqueLabels = selector => [...new Set(allDefinitions().flatMap(selector))];
const unitGroupForLabel = label => { const s = String(label).toLowerCase(); if (/weight|mass|moisture|purity|assay|gsm|thickness|diameter|length|width|height|depth|area|volume|capacity|power|voltage|frequency|rate|speed|pressure|temperature|size|weight|quantity|count|pack|pieces|users|devices|duration/.test(s)) return /volume|capacity|flow|water|fuel/.test(s) ? 'VOLUME' : /area|coverage/.test(s) ? 'AREA' : /length|width|height|depth|diameter|thickness|gsm|size/.test(s) ? 'LENGTH' : /count|quantity|pack|pieces|users|devices/.test(s) ? 'COUNT' : 'WEIGHT'; return null; };
const attributeDataType = label => { const s = String(label).toLowerCase(); if (/date|expiry|manufacture|harvest/.test(s)) return 'date'; if (/number|count|quantity|age|year|weight|volume|length|width|height|depth|capacity|power|voltage|frequency|pressure|rate|size|diameter|thickness|moisture|purity|assay|gsm|speed/.test(s)) return 'measurement'; if (/organic|reusable|sterile|disposable|handmade|downloadable|printable|portable|waterproof|verified|certification/.test(s)) return 'boolean'; return 'string'; };
const labelRegistry = (prefix, labels, metadata = () => ({})) => Object.freeze(Object.fromEntries(labels.map(label => { const id = stableId(prefix, label); return [id, Object.freeze({ id, [`${prefix === 'ATTR' ? 'attribute' : prefix === 'OPTG' ? 'optionGroup' : prefix === 'OPT' ? 'option' : prefix === 'FLT' ? 'filter' : 'feature'}Id`]: id, label, status: 'ACTIVE', ...metadata(label) })]; })));
const ATTRIBUTE_REGISTRY = labelRegistry('ATTR', uniqueLabels(d => d.attributes || []), label => ({ dataType: attributeDataType(label), unitGroup: unitGroupForLabel(label), allowedValues: [], validation: Object.freeze({}) }));
